package ai.fstack.fm1;

import android.util.Base64;
import org.json.*;
import java.io.IOException;
import java.security.MessageDigest;
import java.util.*;

/** iOS-compatible FM1 SLOOP workspace envelope, with checked typed components. */
final class ProjectSnapshot {
 static final String PACKAGE="7c9d269d15d1c1a48e0ebada7ffa2c2aa196c19d51056fd3f760d322322b335f";
 int master=716;
 final LinkedHashMap<String,byte[]> parts=new LinkedHashMap<>();
 static String digest(byte[] bytes)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 void validate()throws Exception{
  Set<String> names=new HashSet<>(Arrays.asList("flash","arrangement"));for(int i=0;i<12;i++)names.add("object"+i);for(int i=0;i<4;i++)names.add("sample"+i);
  if(master<0||master>1023||!parts.keySet().equals(names))throw new IOException("Unsupported or incomplete SLOOP workspace.");
  if(parts.get("flash").length!=1048576||parts.get("object0").length==0)throw new IOException("The workspace is incomplete.");byte[] a=parts.get("arrangement");if(a.length<13||a.length>43)throw new IOException("Invalid song arrangement.");
  for(Map.Entry<String,byte[]> p:parts.entrySet()){int limit=p.getKey().equals("flash")?1048576:p.getKey().startsWith("sample")?81920:65536;if(p.getValue().length>limit)throw new IOException("Oversized workspace component.");}for(int i=0;i<4;i++)if(parts.get("sample"+i).length!=81920)throw new IOException("Incomplete user sample.");
 }
 static ProjectSnapshot capture(long m,int master)throws Exception{if(NativeEngine.kind(m)!=2)throw new IOException("SLOOP 2.7.1 is required.");ProjectSnapshot s=new ProjectSnapshot();s.master=master;s.parts.put("flash",NativeEngine.flash(m));byte[] a=NativeEngine.readPart(m,1,0);if(a.length<13||a[4]!=0||a[5]!=0)throw new IOException("Stop the song and finish SONG REC before saving or exporting.");for(int i:new int[]{1,4,5,6,7})a[i]=0;s.parts.put("arrangement",a);for(int i=0;i<12;i++)s.parts.put("object"+i,NativeEngine.readPart(m,0,i));for(int i=0;i<4;i++)s.parts.put("sample"+i,NativeEngine.readPart(m,2,i));s.validate();return s;}
 ProjectSnapshot copy(){ProjectSnapshot s=new ProjectSnapshot();s.master=master;for(Map.Entry<String,byte[]> p:parts.entrySet())s.parts.put(p.getKey(),p.getValue().clone());return s;}
 ProjectSnapshot projectPayload(){ProjectSnapshot s=copy();s.master=716;byte[] flash=new byte[1048576];Arrays.fill(flash,(byte)255);s.parts.put("flash",flash);for(int i:new int[]{1,10,11})s.parts.put("object"+i,new byte[0]);return s;}
 ProjectSnapshot overlay(ProjectSnapshot current)throws Exception{validate();current.validate();ProjectSnapshot s=current.copy();for(String name:parts.keySet())if(name.equals("object0")||name.equals("arrangement")||name.startsWith("sample")||name.matches("object[2-9]"))s.parts.put(name,parts.get(name).clone());return s;}
 byte[] envelope(String name,boolean backup)throws Exception{if(name.trim().isEmpty()||name.length()>120)throw new IOException("Give this project a name up to 120 characters.");ProjectSnapshot s=backup?this:projectPayload();s.validate();JSONObject object=new JSONObject();object.put("format","FM1 SLOOP workspace").put("version",1).put("id",UUID.randomUUID().toString()).put("name",name.trim()).put("createdAt",System.currentTimeMillis()/1000.0-978307200).put("kind",backup?"backup":"project");JSONObject snapshot=new JSONObject();snapshot.put("version",1).put("packageSHA256",PACKAGE).put("master",s.master);JSONArray array=new JSONArray();for(Map.Entry<String,byte[]> p:s.parts.entrySet())array.put(new JSONObject().put("name",p.getKey()).put("bytes",Base64.encodeToString(p.getValue(),Base64.NO_WRAP)).put("sha256",digest(p.getValue())));snapshot.put("parts",array);object.put("snapshot",snapshot);return object.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 static ProjectSnapshot fromEnvelope(byte[] bytes,String filename)throws Exception{
  if(bytes.length<1||bytes.length>4*1024*1024)throw new IOException("Invalid workspace file size.");JSONObject root=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));String kind=root.getString("kind");if(!root.getString("format").equals("FM1 SLOOP workspace")||root.getInt("version")!=1||root.getString("name").isEmpty()||root.getString("name").length()>120||!(kind.equals("backup")||kind.equals("project"))||!filename.toLowerCase(Locale.ROOT).endsWith(kind.equals("backup")?".fm1backup":".fm1project"))throw new IOException("The file type does not match its project or backup contents.");
  JSONObject snap=root.getJSONObject("snapshot");if(snap.getInt("version")!=1||!snap.getString("packageSHA256").equals(PACKAGE))throw new IOException("This workspace needs the exact SLOOP 2.7.1 release.");ProjectSnapshot s=new ProjectSnapshot();s.master=snap.getInt("master");JSONArray parts=snap.getJSONArray("parts");if(parts.length()!=18)throw new IOException("Incomplete workspace components.");for(int i=0;i<parts.length();i++){JSONObject part=parts.getJSONObject(i);byte[] data=Base64.decode(part.getString("bytes"),Base64.DEFAULT);String name=part.getString("name");if(s.parts.containsKey(name)||!digest(data).equals(part.getString("sha256")))throw new IOException("A workspace checksum failed.");s.parts.put(name,data);}s.validate();return s;
 }
 long create(byte[] packageBytes)throws Exception{validate();if(!digest(packageBytes).equals(PACKAGE))throw new IOException("Wrong SLOOP package.");long m=NativeEngine.create(packageBytes,2);try{if(!NativeEngine.restore(m,parts.get("flash")))throw new IOException("Workspace storage could not be restored.");NativeEngine.transport(m,false);for(int i=1;i<=12;i++){int id=i==12?0:i;if(NativeEngine.writePart(m,0,id,parts.get("object"+id))!=0)throw new IOException("SLOOP rejected a project object.");}if(NativeEngine.commit(m)!=0)throw new IOException("Project commit failed.");if(NativeEngine.writePart(m,1,0,parts.get("arrangement"))!=0)throw new IOException("SLOOP rejected the song arrangement.");for(int i=0;i<4;i++){byte[] data=parts.get("sample"+i);if(NativeEngine.writePart(m,2,i,data)!=0||!Arrays.equals(data,NativeEngine.readPart(m,2,i)))throw new IOException("Sample verification failed.");}if(NativeEngine.commit(m)!=0)throw new IOException("Project commit failed.");NativeEngine.volume(m,master);return m;}catch(Exception e){NativeEngine.destroy(m);throw e;}}
}
